import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsExiting(true), 3200);
    const finish = setTimeout(onComplete, 4200);
    return () => { clearTimeout(timer); clearTimeout(finish); };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#050505] flex items-center justify-center relative overflow-hidden">

      {/* 1. THE AMBIENT ATMOSPHERE (Apple Style) */}
      <motion.div 
        initial={{ opacity: 0, scale: 0.5 }}
        animate={{ opacity: 0.3, scale: 1.5 }}
        transition={{ duration: 3, ease: "easeOut" }}
        className="absolute w-[800px] h-[800px] glow-orb pointer-events-none"
      />

      {/* 2. THE CORE UNIT */}
      <div className={isExiting ? "animate-warp" : ""}>
        <div className="flex flex-col items-center">

          <div className="relative flex items-center">
            {/* T1 */}
            <motion.h1 
              initial={{ x: -100, opacity: 0, filter: "blur(20px)" }}
              animate={{ x: 0, opacity: 1, filter: "blur(0px)" }}
              transition={{ duration: 1.5, ease: [0.16, 1, 0.3, 1] }}
              className="text-[12rem] md:text-[20rem] font-[1000] italic text-chrome leading-none tracking-tighter"
            >
              T
            </motion.h1>

            {/* THE 2 - The Neon Pulse */}
            <motion.div 
              initial={{ scale: 0, rotate: -20 }}
              animate={{ scale: 1, rotate: 12 }}
              transition={{ type: "spring", stiffness: 100, damping: 15, delay: 0.6 }}
              className="relative z-10 mx-[-20px] md:mx-[-40px]"
            >
              {/* Internal High-Voltage Glow */}
              <div className="absolute inset-0 bg-[#FF5B03] blur-[40px] opacity-60 animate-pulse" />

              <div className="bg-[#FF5B03] w-24 h-24 md:w-44 md:h-44 flex items-center justify-center border-b-4 border-r-4 border-black/20 shadow-[0_30px_60px_rgba(0,0,0,0.5)] relative">
                 <span className="text-white text-8xl md:text-[11rem] font-black italic select-none">
                   2
                 </span>
              </div>
            </motion.div>

            {/* T2 */}
            <motion.h1 
              initial={{ x: 100, opacity: 0, filter: "blur(20px)" }}
              animate={{ x: 0, opacity: 1, filter: "blur(0px)" }}
              transition={{ duration: 1.5, ease: [0.16, 1, 0.3, 1], delay: 0.2 }}
              className="text-[12rem] md:text-[20rem] font-[1000] italic text-chrome leading-none tracking-tighter"
            >
              T
            </motion.h1>
          </div>

          {/* THE WORKER TEXT: Minimal & Sophisticated */}
          <motion.div 
            initial={{ opacity: 0, letterSpacing: "0.2em" }}
            animate={{ opacity: 0.8, letterSpacing: "1.5em" }}
            transition={{ duration: 2.5, delay: 1.2 }}
            className="mt-[-20px] md:mt-[-40px] text-[#FDFAD8] font-black text-xl md:text-3xl uppercase italic pl-[1.5em]"
          >
            Worker
          </motion.div>
        </div>
      </div>

      {/* 3. THE "SWIGGY-COOL" LOADING DOTS */}
      <div className="absolute bottom-20 flex gap-3">
        {[...Array(3)].map((_, i) => (
          <motion.div 
            key={i}
            initial={{ opacity: 0.2 }}
            animate={{ opacity: [0.2, 1, 0.2] }}
            transition={{ duration: 1, repeat: Infinity, delay: i * 0.2 }}
            className="w-2 h-2 rounded-full bg-[#CAD23C]"
          />
        ))}
      </div>
    </div>
  );
};

export default WorkerSplash;
